from itertools import combinations
result = []
for c in combinations(opts, 3):
    sel = list(c)
    sel_ids = [x['id'] for x in sel]
    workers = [x['worker'] for x in sel]
    jobs = [x['job'] for x in sel]
    if len(set(workers)) != 3:
        continue
    if len(set(jobs)) != 3:
        continue
    job_set = set(jobs)
    if not all(j in job_set for j in ['j0','j1','j2']):
        continue
    valid_requires = True
    for x in sel:
        for r in x['requires']:
            if r not in sel_ids:
                valid_requires = False
                break
        if not valid_requires:
            break
    if not valid_requires:
        continue
    if valid(sel_ids):
        result = sel_ids
        break

